@import "tailwindcss";

/* ---------------------------------------------------------------------------
   Kevin — AI antenna engineer.

   Operate surface: an engineer is inside a task, not reading a page. The tool
   should disappear into the work, so the palette is restrained and every
   colour that survives carries meaning rather than mood.

   Two colour systems live here and they must not be confused:

   1. UI chrome — one cool neutral ramp plus a single accent. The neutral is
      tinted toward the accent's hue instead of pure grey, so panels read as
      chosen rather than defaulted.
   2. Physics — the three material families the solver actually distinguishes
      (rf/placement.py splits conductors from dielectrics at 1e4 S/m). These
      are the same values the offline renders use, so the app and the deck are
      one product. They are never used for decoration.
--------------------------------------------------------------------------- */

:root {
  /* Ground: near-black with a blue bias, dark enough that the wireframe
     device reads as emissive without bloom. */
  --ink-950: #07090f;
  --ink-900: #0b0e16;
  --ink-850: #10131d;
  --ink-800: #161a26;
  --ink-700: #1f2432;
  --ink-600: #2b3142;

  /* Text ramp. Secondary and tertiary are tinted, never pure grey. */
  --fg: #e6e9f0;
  --fg-muted: #97a0b5;
  --fg-faint: #626b80;

  /* One accent. Actions, focus, the live cursor. Nothing else. */
  --accent: #4c9dff;
  --accent-dim: #2f6dbd;
  --accent-wash: rgba(76, 157, 255, 0.1);

  /* Semantic state, distinct from the accent so "selected" never reads as
     "passing". */
  --pass: #3ddc97;
  --fail: #ff5c72;
  --warn: #ffb648;

  /* Physics — material families. Mirrors rf/viz/theme.py. */
  --em-metal: #8c9eff;
  --em-dielectric: #69f0ae;
  --em-battery: #ff8a65;
  --em-antenna: #ffd740;

  --background: var(--ink-950);
  --foreground: var(--fg);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);

  --color-ink-950: var(--ink-950);
  --color-ink-900: var(--ink-900);
  --color-ink-850: var(--ink-850);
  --color-ink-800: var(--ink-800);
  --color-ink-700: var(--ink-700);
  --color-ink-600: var(--ink-600);

  --color-fg: var(--fg);
  --color-fg-muted: var(--fg-muted);
  --color-fg-faint: var(--fg-faint);

  --color-accent: var(--accent);
  --color-accent-dim: var(--accent-dim);

  --color-pass: var(--pass);
  --color-fail: var(--fail);
  --color-warn: var(--warn);

  --color-em-metal: var(--em-metal);
  --color-em-dielectric: var(--em-dielectric);
  --color-em-battery: var(--em-battery);
  --color-em-antenna: var(--em-antenna);
}

html,
body {
  height: 100%;
  background: var(--background);
  color: var(--foreground);
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  overscroll-behavior: none;
  /* Measurements line up in columns everywhere in this app. */
  font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased;
}

/* The surfaces we did not draw still carry the design. */
::selection {
  background: var(--accent-wash);
  color: var(--fg);
}

::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: var(--ink-700);
  border-radius: 5px;
  border: 2px solid transparent;
  background-clip: content-box;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--ink-600);
  background-clip: content-box;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 3px;
}

input,
textarea,
select,
button {
  font: inherit;
  color: inherit;
}

textarea,
input[type="text"] {
  caret-color: var(--accent);
}

input[type="number"]::-webkit-inner-spin-button,
input[type="number"]::-webkit-outer-spin-button {
  opacity: 0.25;
}

input[type="range"] {
  height: 3px;
  border-radius: 2px;
  background: var(--ink-700);
  appearance: none;
}
input[type="range"]::-webkit-slider-thumb {
  appearance: none;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: var(--accent);
  cursor: pointer;
  border: 2px solid var(--ink-950);
}

/* The agent's reasoning is ambient: present, detailed, never competing with
   the device or the numbers. It fades in rather than appearing. */
@keyframes think-in {
  from {
    opacity: 0;
    transform: translateY(3px);
    filter: blur(2px);
  }
  to {
    opacity: 1;
    transform: none;
    filter: none;
  }
}

.think-in {
  animation: think-in 420ms cubic-bezier(0.16, 1, 0.3, 1) backwards;
}

@media (prefers-reduced-motion: reduce) {
  .think-in {
    animation: none;
  }
}

"use client";

import { useEffect, useRef, useState } from "react";
import { useApp } from "@/lib/store";
import type { BandRequirement } from "@/lib/types";

/**
 * The brief: what the engineer is asking for, and nothing else.
 *
 *   Device      — which geometry the solver actually meshes, and how to
 *                 replace it.
 *   Target band — one band, chosen with its solve cost in view. Extra bands
 *                 are a deliberate addition, never the default.
 *
 * Everything that is reference rather than request (per-band metric grids,
 * the part list) lives elsewhere or behind a disclosure.
 */

/* --------------------------------------------------------------- primitives */

export function SectionTitle({ children }: { children: React.ReactNode }) {
  return (
    <h2 className="text-[11px] font-semibold uppercase tracking-[0.12em] text-fg-muted">
      {children}
    </h2>
  );
}

/** One stroke weight for every glyph in this panel. */
function Icon({
  path,
  size = 13,
  className,
}: {
  path: React.ReactNode;
  size?: number;
  className?: string;
}) {
  return (
    <svg
      viewBox="0 0 16 16"
      width={size}
      height={size}
      fill="none"
      stroke="currentColor"
      strokeWidth={1.5}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      className={className}
    >
      {path}
    </svg>
  );
}

export const Chevron = ({ open }: { open: boolean }) => (
  <Icon
    size={12}
    className={`shrink-0 transition-transform duration-150 ${open ? "rotate-90" : ""}`}
    path={<path d="M6 3.5 10.5 8 6 12.5" />}
  />
);

const FileIn = () => (
  <Icon
    path={
      <>
        <path d="M8 2.5v6.5" />
        <path d="M5.5 6.5 8 9l2.5-2.5" />
        <path d="M2.75 10.5v2a1 1 0 0 0 1 1h8.5a1 1 0 0 0 1-1v-2" />
      </>
    }
  />
);

const Spinner = () => (
  <Icon
    className="animate-spin"
    path={
      <>
        <circle cx="8" cy="8" r="5.25" className="opacity-25" />
        <path d="M8 2.75A5.25 5.25 0 0 1 13.25 8" />
      </>
    }
  />
);

/* ------------------------------------------------------------------- device */

/** Strips the dimensions the catalogue repeats inside the device name. */
const bareName = (n: string) => n.replace(/\s*\([^)]*\)\s*$/, "").trim() || n;

function Tag({ tone, children }: { tone: "pass" | "warn"; children: React.ReactNode }) {
  return (
    <span
      className={`shrink-0 rounded px-1.5 py-px text-[10px] ring-1 ${
        tone === "pass" ? "text-pass ring-pass/30" : "text-warn ring-warn/30"
      }`}
    >
      {children}
    </span>
  );
}

function DeviceCard() {
  const spec = useApp((s) => s.spec);
  const deviceId = useApp((s) => s.deviceId);
  const modelUrl = useApp((s) => s.modelUrl);
  const modelName = useApp((s) => s.modelName);
  const uploading = useApp((s) => s.uploading);
  const setModel = useApp((s) => s.setModel);
  const uploadBlend = useApp((s) => s.uploadBlend);

  const fileRef = useRef<HTMLInputElement>(null);
  const dragDepth = useRef(0);
  const [dragging, setDragging] = useState(false);
  const [problem, setProblem] = useState<string | null>(null);

  const [w, h, t] = spec.board.size_mm;
  const parts = spec.components.length;
  // deviceId is set only after a .blend has been extracted on the backend.
  // Until then the solver meshes the built-in catalogue spec, whatever the
  // viewer happens to be drawing.
  const extracted = deviceId !== null;

  async function load(file: File) {
    const name = file.name.toLowerCase();
    if (name.endsWith(".blend")) {
      // Goes to the backend: parts and materials are extracted there and
      // become the geometry the solver meshes.
      setProblem(null);
      await uploadBlend(file);
      const err = useApp.getState().error;
      if (err) {
        setProblem(
          `${file.name} was not extracted — ${err}. Check the backend is running, then load the file again.`,
        );
      }
      return;
    }
    if (name.endsWith(".glb") || name.endsWith(".gltf")) {
      // Display only: a .glb never reaches the solver.
      const prev = useApp.getState().modelUrl;
      if (prev?.startsWith("blob:")) URL.revokeObjectURL(prev);
      setModel(URL.createObjectURL(file), file.name);
      setProblem(null);
      return;
    }
    setProblem(
      `Kevin reads .blend and .glb. ${file.name} is neither — export the build from Blender and load that.`,
    );
  }

  function clearModel() {
    const prev = useApp.getState().modelUrl;
    if (prev?.startsWith("blob:")) URL.revokeObjectURL(prev);
    setModel(null, null);
    setProblem(null);
  }

  return (
    <section className="border-b border-ink-800 px-4 pb-5 pt-4">
      <SectionTitle>Device</SectionTitle>

      <div
        onDragEnter={(e) => {
          e.preventDefault();
          dragDepth.current += 1;
          setDragging(true);
        }}
        onDragOver={(e) => {
          e.preventDefault();
          e.dataTransfer.dropEffect = "copy";
        }}
        onDragLeave={() => {
          dragDepth.current = Math.max(0, dragDepth.current - 1);
          if (dragDepth.current === 0) setDragging(false);
        }}
        onDrop={(e) => {
          e.preventDefault();
          dragDepth.current = 0;
          setDragging(false);
          const f = e.dataTransfer.files?.[0];
          if (f) void load(f);
        }}
        aria-busy={uploading}
        className={`mt-2.5 rounded-lg border bg-ink-900 transition ${
          dragging
            ? "border-dashed border-accent bg-accent/5"
            : uploading
              ? "border-accent-dim"
              : "border-ink-700"
        }`}
      >
        {/* What the solver meshes. */}
        <div className="px-3 py-2.5">
          <p className="text-[11px] text-fg-muted">Solver geometry</p>
          <p className="mt-0.5 truncate text-[13px] font-medium text-fg">{bareName(spec.name)}</p>
          <p className="mt-0.5 font-mono text-[11px] text-fg-muted">
            {w} × {h} × {t} mm · {parts} parts
          </p>
          <p className="mt-0.5 text-[11px] text-fg-muted">
            {uploading
              ? "Reading parts and materials from your build file — this spec is still what the solver would use."
              : extracted
                ? `Extracted from ${modelName ?? "your build file"}.`
                : "Built-in catalogue spec."}
          </p>
        </div>

        {/* What the viewer draws — said plainly, because they are not always
            the same thing. */}
        <div className="border-t border-ink-800 px-3 py-2.5">
          <p className="text-[11px] text-fg-muted">Viewer</p>
          <div className="mt-0.5 flex items-baseline gap-2">
            <p className="min-w-0 flex-1 truncate text-[12px] text-fg">
              {modelUrl ? (modelName ?? "Loaded mesh") : "iPhone 15 Pro mesh"}
            </p>
            {modelUrl && extracted ? (
              <Tag tone="pass">solver geometry</Tag>
            ) : (
              <Tag tone="warn">display only</Tag>
            )}
          </div>
          <p className="mt-1 text-[11px] leading-relaxed text-fg-muted">
            {modelUrl && extracted
              ? "The same geometry the solver meshes."
              : extracted
                ? "The solver meshes your extracted geometry above, not this mesh."
                : modelUrl
                  ? `Not meshed. The solver still reads the ${bareName(
                      spec.name,
                    )} spec above — load the .blend to make this geometry solvable.`
                  : `191 drawn parts, none of them meshed. The solver reads the ${parts}-part ${bareName(
                      spec.name,
                    )} spec above.`}
          </p>
        </div>

        <div className="flex items-center gap-2 border-t border-ink-800 px-3 py-2">
          <button
            onClick={() => fileRef.current?.click()}
            disabled={uploading}
            className="inline-flex items-center gap-1.5 rounded-md border border-ink-600 px-2.5 py-1.5 text-[11px] font-medium text-fg transition hover:border-accent hover:text-accent disabled:cursor-wait disabled:border-ink-700 disabled:text-fg-muted disabled:hover:border-ink-700 disabled:hover:text-fg-muted"
          >
            {uploading ? <Spinner /> : <FileIn />}
            {uploading ? "Extracting…" : dragging ? "Drop to load" : "Load build file"}
          </button>
          {modelUrl && !extracted && !uploading && (
            <button
              onClick={clearModel}
              className="ml-auto shrink-0 text-[11px] text-fg-muted transition hover:text-fg"
            >
              Remove mesh
            </button>
          )}
        </div>
      </div>

      <p className="mt-2 text-[11px] leading-relaxed text-fg-muted">
        A <span className="font-mono">.blend</span> is extracted on the backend and becomes solver
        geometry. A <span className="font-mono">.glb</span> is display only. Drop one on the card
        above or use the button.
      </p>

      {problem && (
        <p role="alert" className="mt-2 text-[11px] leading-relaxed text-fail">
          {problem}
        </p>
      )}

      <input
        ref={fileRef}
        type="file"
        accept=".blend,.glb,.gltf"
        className="hidden"
        onChange={(e) => {
          const f = e.target.files?.[0];
          e.target.value = "";
          if (f) void load(f);
        }}
      />
    </section>
  );
}

/* -------------------------------------------------------------- target band */

/**
 * Solve cost for one candidate, one band.
 *
 * The solver meshes at lambda/10 taken at the top of the band, so the segment
 * count rises with frequency and the method-of-moments matrix cost rises
 * faster still. Two measured points on the backend's PyNEC path — 83 ms at
 * 2.4835 GHz (Wi-Fi 2.4) and 2007 ms at 5.85 GHz (Wi-Fi 5) — fix the exponent
 * at f^3.72. Every other band here is scaled from those two, not measured.
 */
const REF_GHZ = 2.4835;
const REF_MS = 83;
const COST_EXP = 3.72;

function solveMs(b: BandRequirement) {
  return REF_MS * Math.pow(b.f_high_ghz / REF_GHZ, COST_EXP);
}

function fmtMs(ms: number) {
  if (ms < 10) return `${ms.toFixed(1)} ms`;
  if (ms < 1000) return `${Math.round(ms)} ms`;
  return `${(ms / 1000).toFixed(1)} s`;
}

const ghz = (v: number) => v.toFixed(3);

/** The printed strip rf/placement.py collides against: 1.8 mm wide, 0.9 mm
 *  proud of the surface. Only its length changes with the band. */
const ARM_W_MM = 1.8;
const ARM_H_MM = 0.9;
const C_MM_GHZ = 299.792458;

/** Quarter wave at the band centre — the arm the solver starts from. */
function armMm(b: { f_low_ghz: number; f_high_ghz: number }): number {
  return C_MM_GHZ / ((b.f_low_ghz + b.f_high_ghz) / 2) / 4;
}

function Req({ label, value }: { label: string; value: string }) {
  return (
    <span className="whitespace-nowrap">
      <span className="text-[10px] text-fg-muted">{label} </span>
      <span className="font-mono text-[11px] text-fg">{value}</span>
    </span>
  );
}

function TargetBand() {
  const bands = useApp((s) => s.spec.requirements.bands);
  const enabled = useApp((s) => s.enabledBands);
  const toggleBand = useApp((s) => s.toggleBand);
  const focusBand = useApp((s) => s.focusBand);
  const setFocusBand = useApp((s) => s.setFocusBand);
  const running = useApp((s) => s.running);

  const [primaryId, setPrimaryId] = useState<string | null>(null);
  const [extrasOpen, setExtrasOpen] = useState(false);
  const didInit = useRef(false);

  // The brief opens on one band. Multi-band is legitimate but costly, so it
  // has to be asked for: this narrows the store's default selection to the
  // cheapest useful target once, using the store's own action.
  useEffect(() => {
    if (didInit.current) return;
    didInit.current = true;
    const s = useApp.getState();
    const ids = s.spec.requirements.bands.map((b) => b.id);
    const want = ids.includes("wifi24") ? "wifi24" : (s.enabledBands[0] ?? ids[0]);
    if (!want) return;
    const start = s.enabledBands;
    if (!start.includes(want)) s.toggleBand(want);
    for (const id of start) if (id !== want) s.toggleBand(id);
    setPrimaryId(want);
  }, []);

  const primary =
    bands.find((b) => b.id === primaryId && enabled.includes(b.id)) ??
    bands.find((b) => enabled.includes(b.id)) ??
    null;
  const extras = bands.filter((b) => enabled.includes(b.id) && b.id !== primary?.id);
  const others = bands.filter((b) => b.id !== primary?.id);
  const totalMs = bands
    .filter((b) => enabled.includes(b.id))
    .reduce((sum, b) => sum + solveMs(b), 0);
  const focused = !!primary && focusBand === primary.id;

  /** One band holds the primary slot; choosing a new one swaps it out. */
  function choose(id: string) {
    if (running) return;
    const s = useApp.getState();
    if (!s.enabledBands.includes(id)) s.toggleBand(id);
    const prev = primary?.id;
    if (prev && prev !== id && useApp.getState().enabledBands.includes(prev)) s.toggleBand(prev);
    setPrimaryId(id);
  }

  return (
    <section className="border-b border-ink-800 px-4 pb-5 pt-5">
      <div className="flex items-baseline justify-between">
        <SectionTitle>Target band</SectionTitle>
        <span className="text-[10px] text-fg-muted">per solve</span>
      </div>

      <div role="radiogroup" aria-label="Primary target band" className="mt-2.5 grid grid-cols-2 gap-1">
        {bands.map((b) => {
          const isPrimary = b.id === primary?.id;
          const on = enabled.includes(b.id);
          return (
            <button
              key={b.id}
              role="radio"
              aria-checked={isPrimary}
              disabled={running}
              onClick={() => choose(b.id)}
              title={`${b.name} · ${b.service} · ${ghz(b.f_low_ghz)}–${ghz(b.f_high_ghz)} GHz`}
              className={`flex items-center gap-1.5 rounded-md border px-2 py-1.5 text-left transition disabled:cursor-not-allowed disabled:opacity-60 ${
                isPrimary
                  ? "border-accent/60 bg-accent/10"
                  : "border-ink-700 hover:border-ink-600 hover:bg-ink-850"
              }`}
            >
              <span
                className="h-1.5 w-1.5 shrink-0 rounded-full"
                style={{ background: on ? b.color : "var(--ink-600)" }}
              />
              <span className={`truncate text-[11px] ${isPrimary ? "text-fg" : "text-fg-muted"}`}>
                {b.short}
              </span>
              <span className="ml-auto shrink-0 font-mono text-[10px] text-fg-muted">
                {fmtMs(solveMs(b))}
              </span>
            </button>
          );
        })}
      </div>

      <p className="mt-2 text-[11px] leading-relaxed text-fg-muted">
        Mesh pitch is λ/10 at the top of the band, so a solve costs about{" "}
        <span className="font-mono">f^3.7</span> — 83 ms measured at 2.4835 GHz, 2.0 s at 5.85 GHz.
      </p>

      {primary ? (
        <div className="mt-3 border-t border-ink-800 pt-3">
          <div className="flex items-baseline gap-2">
            <h3 className="min-w-0 flex-1 truncate text-[13px] font-medium text-fg">
              {primary.name}
            </h3>
            <span className="shrink-0 font-mono text-[10px] text-fg-muted">
              {ghz(primary.f_low_ghz)}–{ghz(primary.f_high_ghz)} GHz
            </span>
          </div>
          <div className="mt-1.5 flex flex-wrap items-baseline gap-x-3 gap-y-1">
            <Req label="S11" value={`≤ ${primary.s11_db_max} dB`} />
            <Req label="Efficiency" value={`≥ ${Math.round(primary.efficiency_min * 100)}%`} />
            <Req label="Clearance" value={`≥ ${primary.clearance_mm} mm`} />
          </div>
          {/* The band is not just a frequency: it fixes how much room the
              radiator needs. A quarter wave at 850 MHz is 87 mm of arm in a
              147 mm phone; at 5 GHz it is 13 mm. That is why the legal region
              and the placement map differ per band, and why the same device
              can host one antenna and refuse another. */}
          <div className="mt-1.5 flex flex-wrap items-baseline gap-x-3 gap-y-1">
            <Req
              label="Radiator"
              value={`${armMm(primary).toFixed(0)} × ${ARM_W_MM} × ${ARM_H_MM} mm`}
            />
            <Req label="Type" value={(primary.antenna_types ?? ["IFA"]).join(" / ")} />
          </div>
          {enabled.length > 1 && (
            <button
              aria-pressed={focused}
              onClick={() => setFocusBand(focused ? null : primary.id)}
              title="Show only this band's candidates in the viewer"
              className={`mt-2 text-[11px] transition ${
                focused ? "text-accent" : "text-fg-muted hover:text-fg"
              }`}
            >
              {focused ? "Showing this band only" : "Focus in viewer"}
            </button>
          )}
        </div>
      ) : (
        <p className="mt-3 border-t border-ink-800 pt-3 text-[11px] leading-relaxed text-fg-muted">
          No band selected. Pick one above — Kevin needs a target before it can propose a placement.
        </p>
      )}

      <div className="mt-3 border-t border-ink-800 pt-3">
        <button
          aria-expanded={extrasOpen}
          onClick={() => setExtrasOpen((o) => !o)}
          className="flex w-full items-center gap-1.5 text-[11px] text-fg-muted transition hover:text-fg"
        >
          <Chevron open={extrasOpen} />
          <span>Also solve another band</span>
          <span className="ml-auto font-mono text-[10px]">
            {extras.length ? `+${extras.length}` : "none"}
          </span>
        </button>

        {extras.length > 0 && (
          <p className="mt-1.5 pl-[18px] text-[11px] leading-relaxed text-fg-muted">
            {extras.map((b) => b.name).join(", ")} · every candidate costs{" "}
            <span className="font-mono text-fg">{fmtMs(totalMs)}</span> across{" "}
            {enabled.length} bands.
          </p>
        )}

        {extrasOpen && (
          <>
            <ul className="mt-2 -mx-2">
              {others.map((b) => {
                const on = enabled.includes(b.id);
                return (
                  <li key={b.id}>
                    <label
                      className={`flex items-center gap-2 rounded-md px-2 py-1.5 transition ${
                        running ? "cursor-not-allowed opacity-60" : "cursor-pointer hover:bg-ink-850"
                      }`}
                    >
                      <input
                        type="checkbox"
                        checked={on}
                        disabled={running}
                        onChange={() => toggleBand(b.id)}
                        className="accent-accent"
                      />
                      <span
                        className="h-1.5 w-1.5 shrink-0 rounded-full"
                        style={{ background: on ? b.color : "var(--ink-600)" }}
                      />
                      <span className="min-w-0 flex-1 truncate text-[11px] text-fg">{b.name}</span>
                      <span className="shrink-0 font-mono text-[10px] text-fg-muted">
                        {fmtMs(solveMs(b))}
                      </span>
                    </label>
                  </li>
                );
              })}
            </ul>
            <p className="mt-1.5 text-[11px] leading-relaxed text-fg-muted">
              Each added band is a full extra solve on every candidate the agent tries.
            </p>
          </>
        )}
      </div>
    </section>
  );
}

export function SpecPanel() {
  return (
    <>
      <DeviceCard />
      <TargetBand />
    </>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { useApp, type AgentKind } from "@/lib/store";
import type { AgentMessage } from "@/lib/types";

/**
 * The right rail is the agent's work: the spec the engineer writes, who runs
 * it, and everything the run says back.
 *
 * Three things carry the design here.
 *
 * 1. The prompt is the spec, so it is the first thing in the rail and the
 *    biggest input in the app. Once a run starts it collapses to a recap —
 *    the transcript is what matters then — and comes back on "Edit spec".
 * 2. The reasoning is ambient. Prose sits at --fg-muted (7.5:1 on the ground:
 *    recessive, never unreadable), 12px on a 24px rhythm, fading in with
 *    .think-in as each line lands. Measurements are the only monospace.
 * 3. The three message kinds the backend emits read as three different
 *    things: orchestrator narration is a hairline break in the timeline, a
 *    solve landing is a measurement block with its verdict, and a decision is
 *    a labelled statement in full text colour. Nothing else is emphasised.
 */

const LABEL = "text-[10px] font-semibold uppercase tracking-[0.14em] text-fg-muted";

/* ------------------------------------------------------------------ marks */
/* Drawn, single 1.5 stroke. No glyph icons anywhere in this panel. */

function AlertMark({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 16 16"
      width={14}
      height={14}
      fill="none"
      stroke="currentColor"
      strokeWidth={1.5}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      className={className}
    >
      <path d="M8 2.4 14.6 13.6H1.4Z" />
      <path d="M8 6.6v3" />
      <path d="M8 11.7h.01" />
    </svg>
  );
}

function Spinner({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 16 16"
      width={13}
      height={13}
      fill="none"
      stroke="currentColor"
      strokeWidth={1.5}
      aria-hidden="true"
      className={`animate-spin ${className ?? ""}`}
    >
      <circle cx="8" cy="8" r="6" className="opacity-30" />
      <path d="M14 8a6 6 0 0 0-6-6" strokeLinecap="round" />
    </svg>
  );
}

/* ------------------------------------------------------------------ agents */

interface AgentChoice {
  id: AgentKind;
  name: string;
  /** The trade-off, stated where the choice is made. */
  blurb: string;
  /** Time and cost, aligned across the three so they compare at a glance. */
  meta: string;
}

const AGENT_CHOICES: AgentChoice[] = [
  {
    id: "mock",
    name: "Mock",
    blurb: "Heuristic placement, real PyNEC solves. No agent reasoning in the transcript.",
    meta: "seconds · free",
  },
  {
    id: "replay",
    name: "Replay",
    blurb: "A recorded live Devin run, played back — the real agent's reasoning, no quota.",
    meta: "instant · free",
  },
  {
    id: "devin",
    name: "Devin",
    blurb: "The live agent, reasoning on this device now. Metered, and slow enough to watch.",
    meta: "~2.5 min · uses quota",
  },
];

const agentName = (id: AgentKind) => AGENT_CHOICES.find((a) => a.id === id)?.name ?? id;

/* ------------------------------------------------- reading the message feed */

type Line =
  | { t: "note"; text: string }
  | { t: "step"; text: string }
  | { t: "prose"; text: string }
  | { t: "decision"; label: string; body: string }
  | { t: "outcome"; label: string; body: string; state: "pass" | "warn" }
  | { t: "failure"; body: string }
  | {
      t: "result";
      head: string;
      metrics: string[];
      verdict: "pass" | "fail" | "error" | null;
      note: string;
    };

/** `c3 (IFA, Wi-Fi 2.4): S11 -14.2 dB at 2.44 GHz, … -> PASS. notes` */
function readResult(text: string): Line {
  const i = text.indexOf(": ");
  const head = i > 0 ? text.slice(0, i) : text;
  const rest = i > 0 ? text.slice(i + 2) : "";
  if (!rest || /solve failed/i.test(rest)) {
    return { t: "result", head, metrics: [], verdict: "error", note: rest };
  }
  const arrow = rest.indexOf(" -> ");
  const measured = arrow > 0 ? rest.slice(0, arrow) : rest;
  const tail = arrow > 0 ? rest.slice(arrow + 4) : "";
  const verdict = /^PASS/.test(tail) ? "pass" : /^FAIL/.test(tail) ? "fail" : null;
  return {
    t: "result",
    head,
    metrics: measured.split(", ").map((s) => s.trim()).filter(Boolean),
    verdict,
    note: tail.replace(/^(PASS|FAIL)\.?/, "").trim(),
  };
}

/** Decision events arrive as `accept_bottom_edge: rationale…`. */
const DECISION = /^([A-Za-z][A-Za-z0-9_-]*(?: [A-Za-z0-9_-]+){0,2}):\s+([\s\S]+)$/;

function read(m: AgentMessage): Line {
  if (m.role === "user") return { t: "note", text: m.text };
  if (m.kind === "step") return { t: "step", text: m.text };
  if (m.kind === "result") return readResult(m.text);

  if (/^run failed:/i.test(m.text)) {
    return { t: "failure", body: m.text.replace(/^run failed:\s*/i, "") };
  }
  const hit = DECISION.exec(m.text);
  if (!hit) return { t: "prose", text: m.text };

  const label = hit[1].replace(/_/g, " ");
  const body = hit[2];
  if (/^recommendation$/i.test(label)) {
    return {
      t: "outcome",
      label: "Recommendation",
      body,
      state: /requirements met/i.test(body) ? "pass" : "warn",
    };
  }
  return { t: "decision", label: label.charAt(0).toUpperCase() + label.slice(1), body };
}

function TranscriptLine({ line }: { line: Line }) {
  switch (line.t) {
    case "step":
      // Orchestrator narration: a break in the timeline, not something to read
      // twice. The rule does the separating; the words stay small.
      return (
        <div className="think-in pt-1">
          <div className="h-px bg-ink-800" />
          <p className="pt-2 text-[11px] leading-5 text-fg-muted">{line.text}</p>
        </div>
      );

    case "prose":
      return <p className="think-in text-[12px] leading-6 text-fg-muted">{line.text}</p>;

    case "decision":
      return (
        <div className="think-in border-l border-ink-600 pl-3">
          <p className="text-[11px] font-semibold text-fg">{line.label}</p>
          <p className="mt-1 text-[12px] leading-6 text-fg-muted">{line.body}</p>
        </div>
      );

    case "outcome":
      return (
        <div
          className={`think-in border-l pl-3 ${
            line.state === "pass" ? "border-pass" : "border-warn"
          }`}
        >
          <p className="text-[11px] font-semibold text-fg">{line.label}</p>
          <p className="mt-1 text-[12px] leading-6 text-fg">{line.body}</p>
        </div>
      );

    case "failure":
      return (
        <div className="think-in border-l border-fail pl-3">
          <p className="text-[11px] font-semibold text-fail">Run failed</p>
          <p className="mt-1 text-[12px] leading-6 text-fg-muted">{line.body}</p>
        </div>
      );

    case "note":
      return (
        <div className="think-in border-l border-accent-dim pl-3">
          <p className={LABEL}>Your note</p>
          <p className="mt-1 text-[12px] leading-6 text-fg">{line.text}</p>
        </div>
      );

    case "result":
      // A solve landing. Monospace because every token is a measurement.
      return (
        <div
          className={`think-in border-l pl-3 ${
            line.verdict === "pass"
              ? "border-pass"
              : line.verdict === "fail" || line.verdict === "error"
                ? "border-fail"
                : "border-ink-600"
          }`}
        >
          <div className="flex items-baseline gap-2">
            <span className="min-w-0 flex-1 truncate font-mono text-[11px] text-fg">
              {line.head}
            </span>
            {line.verdict && (
              <span
                className={`shrink-0 font-mono text-[10px] tracking-[0.12em] ${
                  line.verdict === "pass" ? "text-pass" : "text-fail"
                }`}
              >
                {line.verdict === "error" ? "NO SOLVE" : line.verdict.toUpperCase()}
              </span>
            )}
          </div>
          {!!line.metrics.length && (
            <p className="mt-1 font-mono text-[11px] leading-5 text-fg-muted">
              {line.metrics.map((metric, i) => (
                <span key={metric}>
                  {i > 0 && <span className="px-1.5 text-fg-faint">·</span>}
                  {metric}
                </span>
              ))}
            </p>
          )}
          {!!line.note && (
            <p className="mt-1 text-[11px] leading-5 text-fg-muted">{line.note}</p>
          )}
        </div>
      );
  }
}

/* -------------------------------------------------------------- the panel */

function elapsedLabel(seconds: number) {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${m}:${String(s).padStart(2, "0")}`;
}

export function AgentPanel() {
  const prompt = useApp((s) => s.prompt);
  const setPrompt = useApp((s) => s.setPrompt);
  const startRun = useApp((s) => s.startRun);
  const wantMedia = useApp((s) => s.wantMedia);
  const setWantMedia = useApp((s) => s.setWantMedia);
  const poll = useApp((s) => s.poll);
  const running = useApp((s) => s.running);
  const planning = useApp((s) => s.planning);
  const messages = useApp((s) => s.messages);
  const jobs = useApp((s) => s.jobs);
  const error = useApp((s) => s.error);
  const runId = useApp((s) => s.runId);
  const agent = useApp((s) => s.agent);
  const setAgent = useApp((s) => s.setAgent);
  const agentFellBack = useApp((s) => s.agentFellBack);
  const tapeOtherDevice = useApp((s) => s.tapeOtherDevice);
  const sendNote = useApp((s) => s.sendNote);
  const enabledBands = useApp((s) => s.enabledBands);
  const bands = useApp((s) => s.spec.requirements.bands);

  const [note, setNote] = useState("");
  const [editingSpec, setEditingSpec] = useState(false);
  const [elapsed, setElapsed] = useState(0);
  const feedRef = useRef<HTMLDivElement>(null);

  // The study finishing is not the end of the run: the evidence renders after
  // run_finished so it can never gate the result, which means `running` goes
  // false while artifacts are still landing. Keep polling — more slowly — until
  // the media stage is done too, or the gallery stays empty forever.
  const stage = useApp((s) => s.stage);
  const rendering = stage === "media";
  useEffect(() => {
    if (!runId || (!running && !rendering)) return;
    const t = setInterval(() => void poll(), running ? 600 : 2000);
    return () => clearInterval(t);
  }, [running, rendering, runId, poll]);

  // Devin runs for minutes: a clock is the difference between "working" and
  // "stuck". It freezes where the run ended.
  useEffect(() => {
    if (!running) return;
    const t0 = Date.now();
    setElapsed(0);
    const t = setInterval(() => setElapsed(Math.round((Date.now() - t0) / 1000)), 1000);
    return () => clearInterval(t);
  }, [running, runId]);

  useEffect(() => {
    // Only chase the transcript once there is one. The spec editor lives in
    // this same scroller, so an unguarded scroll-to-bottom on mount pushes the
    // primary input — the thing the engineer is meant to type into first —
    // off the top of the panel.
    if (!messages.length) return;
    feedRef.current?.scrollTo({ top: feedRef.current.scrollHeight, behavior: "smooth" });
  }, [messages.length]);

  // The spec is echoed into the feed as message u0; it already has a home at
  // the top of the rail, so it does not open the transcript as well.
  const transcript = messages.filter((m) => m.id !== "u0");
  const started = !!runId || messages.length > 0;
  const specOpen = !started || editingSpec;
  const bandShorts = bands.filter((b) => enabledBands.includes(b.id)).map((b) => b.short);
  const canRun = !running && !!prompt.trim() && bandShorts.length > 0;
  const solved = jobs.filter((j) => j.status === "complete").length;
  const failedJobs = jobs.filter((j) => j.status === "failed").length;

  // Disabled controls have to say why, and name the way out.
  const blocker = !prompt.trim()
    ? "Write the spec first — one line naming the band and the limits is enough."
    : !bandShorts.length
      ? "Enable a band in the device panel — the study has nothing to solve for."
      : null;

  const run = () => {
    if (!canRun) return;
    setEditingSpec(false);
    void startRun();
  };

  return (
    <div className="flex h-full flex-col bg-ink-950">
      <header className="flex h-11 shrink-0 items-center gap-3 border-b border-ink-800 px-4">
        <h2 className={LABEL}>Agent</h2>
        {started && (
          <div className="ml-auto flex items-center gap-2">
            {running && <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-accent" />}
            <span className="text-[11px] text-fg-muted">
              {running ? (planning ? "Planning" : "Simulating") : "Finished"}
            </span>
            {elapsed > 0 && (
              <span className="font-mono text-[11px] text-fg-muted">{elapsedLabel(elapsed)}</span>
            )}
          </div>
        )}
      </header>

      {/* The spec, once a run owns the rail: still legible, no longer the
          thing you are looking at. */}
      {started && !editingSpec && (
        <div className="shrink-0 border-b border-ink-800 px-4 py-3">
          <div className="flex items-baseline gap-3">
            <h3 className={LABEL}>Spec</h3>
            <span className="ml-auto text-[11px] text-fg-muted">{agentName(agent)}</span>
            {!running && (
              <button
