export function ResultsDock() {
  const tab = useApp((s) => s.dockTab);
  const setTab = useApp((s) => s.setDockTab);
  const candidates = useApp((s) => s.candidates);
  const report = useApp((s) => s.report);
  const running = useApp((s) => s.running);
  const media = useApp((s) => s.media);
  const stage = useApp((s) => s.stage);
  const wantMedia = useApp((s) => s.wantMedia);

  if (!candidates.length) {
    return (
      <p className="px-4 py-3 text-[11px] text-fg-muted">
        {running
          ? "Planning placements. Candidates appear here as the agent proposes them."
          : "This run produced no candidates. The agent feed says why."}
      </p>
    );
  }

  // A tab only exists once it has something behind it, so the strip never
  // offers a dead end.
  const hasEvidence = media.length > 0 || stage === "media" || wantMedia;
  const tabs = (
    ["results", ...(report ? ["report"] : []), ...(hasEvidence ? ["evidence"] : [])] as const
  ) as readonly ("results" | "report" | "evidence")[];
  const showing = tabs.includes(tab) ? tab : "results";
  return (
    <div className="flex h-full min-h-0 flex-col">
      <BandCoverage />

      <div className="flex min-h-0 flex-1">
        <div className="flex min-w-0 flex-1 flex-col border-r border-ink-800">
          {tabs.length > 1 && (
            <div className="flex shrink-0 gap-4 border-b border-ink-800 px-4">
              {tabs.map((t) => (
                <button
                  key={t}
                  type="button"
                  onClick={() => setTab(t)}
                  aria-current={showing === t || undefined}
                  className={`-mb-px border-b py-1.5 text-[11px] transition-colors ${
                    showing === t
                      ? "border-accent text-fg"
                      : "border-transparent text-fg-muted hover:text-fg"
                  }`}
                >
                  {t === "results"
                    ? `Candidates (${candidates.length})`
                    : t === "report"
                      ? "Report"
                      : `Evidence${media.length ? ` (${shownCount(media)})` : ""}`}
                </button>
              ))}
            </div>
          )}
          {showing === "results" ? (
            <CandidateTable />
          ) : showing === "report" ? (
            <ReportView />
          ) : (
            <EvidenceGallery />
          )}
        </div>

        {/* The sweep belongs beside the table; the gallery is already pictures
            and wants the width. */}
        {showing !== "evidence" && (
          <aside className="w-[380px] shrink-0">
            <S11Chart />
          </aside>
        )}
      </div>
    </div>
  );
}
