  const showLabels = useApp((s) => s.showLabels);
  const showShaded = useApp((s) => s.showShaded);
  const layers: Record<Layer, boolean> = { showPins, showKeepouts, showLabels, showShaded };
  const bands = useApp((s) => s.spec.requirements.bands);
  const enabled = useApp((s) => s.enabledBands);
  const viewMode = useApp((s) => s.viewMode);
  const focusBand = useApp((s) => s.focusBand);
  const setFocusBand = useApp((s) => s.setFocusBand);
  const setViewMode = useApp((s) => s.setViewMode);
  const modelUrl = useApp((s) => s.modelUrl);
  const candidates = useApp((s) => s.candidates);

  return (
    <div className="relative h-full w-full overflow-hidden bg-[#070a12]">
      <Scene />

      <div className="pointer-events-none absolute inset-0 p-3">
        {/* camera presets */}
        <div className="pointer-events-auto flex items-center gap-1">
          {Object.keys(VIEW_PRESETS).map((k) => (
            <HudButton
              key={k}
              onClick={() => window.dispatchEvent(new CustomEvent("view-preset", { detail: k }))}
            >
              {k}
            </HudButton>
          ))}
        </div>

        {/* what to draw */}
        <div className="pointer-events-auto absolute right-3 top-3 flex flex-col items-end gap-1">
          {LAYERS.map(([key, label]) => (
            <HudButton key={key} active={layers[key]} onClick={() => toggle(key)}>
              {label}
            </HudButton>
          ))}
        </div>

        {/* which candidates: the chosen set, or every candidate for one band */}
        {candidates.length > 0 && (
          <div className="pointer-events-auto absolute bottom-3 right-3 flex items-center gap-1">
            <HudButton active={viewMode === "system"} onClick={() => setViewMode("system")}>
              Chosen
            </HudButton>
            <HudButton active={viewMode === "focus"} onClick={() => setViewMode("focus")}>
              All for band
            </HudButton>
            {viewMode === "focus" && (
              <select
                value={focusBand ?? ""}
                onChange={(e) => setFocusBand(e.target.value)}
                className="rounded-md bg-ink-850/80 px-2 py-1 text-[11px] text-fg outline-none"
              >
                {bands
                  .filter((b) => enabled.includes(b.id))
                  .map((b) => (
                    <option key={b.id} value={b.id}>
                      {b.name}
                    </option>
                  ))}
              </select>
            )}
          </div>
        )}

        {/* Pulls the real 191-part stack apart along its thinnest axis, which
            is how a teardown lays a phone out — and the only view where you
            can see which layer the antenna is actually fighting. Hidden for an
            uploaded model: that path draws a shaded mesh, not per-part line
            art, so there is nothing to separate. */}
        {!modelUrl && (
          <div className="pointer-events-auto absolute bottom-3 left-3 flex w-56 items-center gap-3 rounded-md bg-ink-850/80 px-3 py-2 backdrop-blur">
            <span className="text-[11px] text-fg-muted">Explode</span>
            <input
              type="range"
              min={0}
              max={1}
              step={0.01}
              value={explode}
              onChange={(e) => setExplode(parseFloat(e.target.value))}
              className="min-w-0 flex-1"
            />
            <span className="w-8 text-right font-mono text-[10px] text-fg-faint">
              {(explode * 100).toFixed(0)}%
            </span>
          </div>
        )}
      </div>
    </div>
  );
}
=============== SpectrumStrip
"use client";

import { useApp } from "@/lib/store";
import { detuneMhz, rankKey, verdictOf } from "@/lib/evidence";
import type { SimResult } from "@/lib/types";
import { VerdictDot } from "./Verdict";

/**
 * Band coverage: the one question the candidate table cannot answer at a
 * glance — of the bands this study was asked to cover, which ones now have a
 * design that lands inside the window, and how far off the rest are.
 *
 * The old log-frequency strip is gone. It painted the requested bands as
 * coloured blocks on a 0.6-6.5 GHz axis, where an 70 MHz cellular window is
 * two pixels wide and a 40 MHz miss is invisible — decoration where the
 * detuning is the whole point. Each band now gets its own track, scaled to
 * its own window, so "in band" and "80 MHz low" look different.
 */

/** How much spectrum either side of the window a track shows, in window widths. */
const CONTEXT = 1.6;
const MAX_CONTEXT = 8;

const clamp = (v: number, lo: number, hi: number) => Math.min(Math.max(v, lo), hi);

export function BandCoverage() {
  const spec = useApp((s) => s.spec);
  const candidates = useApp((s) => s.candidates);
  const results = useApp((s) => s.results);
  const placements = useApp((s) => s.placements);
  const selected = useApp((s) => s.selectedCandidate);
  const selectCandidate = useApp((s) => s.selectCandidate);

  const cells = spec.requirements.bands
    .filter((band) => candidates.some((c) => c.band_id === band.id))
    .map((band) => {
      const mine = candidates.filter((c) => c.band_id === band.id);
      const done = mine
        .map((c) => results[c.candidate_id])
        .filter((r): r is SimResult => r?.status === "complete");
      const chosenId = placements[band.id];
      const best =
        (chosenId && results[chosenId]?.status === "complete" ? results[chosenId] : undefined) ??
        [...done].sort((a, b) => rankKey(b, band) - rankKey(a, band))[0];
      const solving = mine.some((c) => results[c.candidate_id]?.status === "running");
      const centre = (band.f_low_ghz + band.f_high_ghz) / 2;
      const width = band.f_high_ghz - band.f_low_ghz;
      const half = Math.min(
        Math.max(width * CONTEXT, ...done.map((r) => Math.abs(r.resonant_ghz - centre) * 1.15)),
        width * MAX_CONTEXT,
      );
      const at = (f: number) => clamp(((f - (centre - half)) / (2 * half)) * 100, 0, 100);
      return {
        band,
        best,
        done,
        at,
        verdict: verdictOf(best),
        solving,
        holds: mine.some((c) => c.candidate_id === selected),
      };
    });

  if (!cells.length) return null;

  const met = cells.filter((c) => c.verdict === "pass").length;

  return (
    <section className="border-b border-ink-800 px-4 pb-2 pt-2.5">
      <div className="mb-2 flex items-baseline gap-3">
        <h2 className="text-[11px] font-medium text-fg">
          {met} of {cells.length} bands met
        </h2>
        <span className="ml-auto truncate font-mono text-[10px] text-fg-muted">
          each track spans its own band · tick = simulated resonance
        </span>
      </div>

      <div className="flex items-stretch gap-1">
        {cells.map(({ band, best, done, at, verdict, holds, solving }) => {
          const detune = best ? detuneMhz(best, band) : 0;
          return (
            <button
              key={band.id}
              type="button"
              disabled={!best}
              aria-current={holds || undefined}
              onClick={() => {
                const chosen = placements[band.id];
                const id =
                  chosen ??
                  [...candidates.filter((c) => c.band_id === band.id)].sort(
                    (a, b) =>
                      rankKey(results[b.candidate_id], band) -
                      rankKey(results[a.candidate_id], band),
                  )[0]?.candidate_id;
                if (id) selectCandidate(id);
              }}
              title={
                best
                  ? `${band.name} · window ${band.f_low_ghz}-${band.f_high_ghz} GHz · best resonance ${best.resonant_ghz.toFixed(3)} GHz${
                      detune === 0
                        ? " (inside the window)"
                        : ` (${Math.abs(detune).toFixed(0)} MHz ${detune < 0 ? "low" : "high"})`
                    } · ${done.length} candidate${done.length === 1 ? "" : "s"} simulated`
                  : `${band.name} · no completed simulation yet`
              }
              className={`min-w-0 flex-1 rounded-sm px-2 py-1.5 text-left transition-colors disabled:cursor-default ${
                holds ? "bg-accent/10" : "enabled:hover:bg-ink-900"
              }`}
            >
              <span className="flex items-baseline gap-1.5">
                <VerdictDot v={verdict} />
                <span className={`truncate text-[11px] ${holds ? "text-fg" : "text-fg-muted"}`}>
                  {band.short}
                </span>
                <span className="ml-auto shrink-0 font-mono text-[10px] text-fg-muted">
                  {best
                    ? `${best.s11_min_db.toFixed(1)} dB`
                    : solving
                      ? "solving"
                      : "queued"}
                </span>
              </span>

              <span className="relative mt-1.5 block h-2.5">
                <span className="absolute inset-x-0 top-1/2 h-px bg-ink-700" />
                <span
                  className="absolute inset-y-0 border-x border-ink-600 bg-ink-800"
                  style={{
                    left: `${at(band.f_low_ghz)}%`,
                    width: `${Math.max(at(band.f_high_ghz) - at(band.f_low_ghz), 1)}%`,
                  }}
                />
                {done.map((r) => (
                  <span
                    key={r.candidate_id}
                    className="absolute inset-y-1 w-px bg-ink-600"
                    style={{ left: `${at(r.resonant_ghz)}%` }}
                  />
                ))}
                {best && (
                  <span
                    className={`absolute inset-y-0 w-0.5 -translate-x-px ${
                      verdict === "pass" ? "bg-pass" : "bg-fail"
                    }`}
                    style={{ left: `${at(best.resonant_ghz)}%` }}
                  />
                )}
              </span>
            </button>
          );
        })}
      </div>
    </section>
  );
}

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";
import {
  BW_LEVEL_DB,
  bandwidthSpan,
  niceTicks,
  verdictOf,
} from "@/lib/evidence";
import { useApp } from "@/lib/store";
import type { BandRequirement, SimResult } from "@/lib/types";
import { VerdictChip } from "./Verdict";

/**
 * Reflection against frequency for the candidate under inspection — the piece
 * of evidence the whole loop exists to produce.
 *
 * Drawn by hand rather than by a chart library so every mark is deliberate and
 * every colour is a token: the target band window, the S11 the design has to
 * stay under, where it actually resonates, and how much usable bandwidth that
 * leaves. The accent draws the selected trace and nothing else; pass/fail
 * colour states the verdict; the material colours belong to the device.
 */

const PAD = { top: 16, right: 14, bottom: 30, left: 44 };

function Quiet({ children }: { children: React.ReactNode }) {
  return (
    <div className="flex h-full items-center justify-center px-6 text-center text-[11px] leading-relaxed text-fg-muted">
      <p className="max-w-[26ch]">{children}</p>
    </div>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return (
    <div className="min-w-0">
      <dt className="truncate text-[9px] uppercase tracking-[0.1em] text-fg-muted">{label}</dt>
      <dd className="truncate font-mono text-[11px] text-fg">{value}</dd>
    </div>
  );
}

function useSize<T extends HTMLElement>() {
  const ref = useRef<T>(null);
  const [size, setSize] = useState({ w: 0, h: 0 });
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver(([entry]) => {
      const { width, height } = entry.contentRect;
      setSize((s) =>
        Math.abs(s.w - width) < 0.5 && Math.abs(s.h - height) < 0.5
          ? s
          : { w: width, h: height },
      );
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  return { ref, ...size };
}

function Plot({
  res,
  band,
  others,
}: {
  res: SimResult;
  band: BandRequirement;
  others: SimResult[];
}) {
  const { ref, w, h } = useSize<HTMLDivElement>();
  const clip = `s11-clip-${useId().replace(/:/g, "")}`;

  const g = useMemo(() => {
    const plotW = w - PAD.left - PAD.right;
    const plotH = h - PAD.top - PAD.bottom;
    if (plotW < 60 || plotH < 50) return null;

    const curves = [res, ...others].map((r) => r.s11_curve).filter((c) => c.length > 1);
    if (!curves.length) return null;
    const fAll = curves.flat().map((p) => p.f_ghz);
    let x0 = Math.min(band.f_low_ghz, ...fAll);
    let x1 = Math.max(band.f_high_ghz, ...fAll);
    const padX = Math.max((x1 - x0) * 0.04, 1e-4);
    x0 -= padX;
    x1 += padX;

    const dbMin = Math.min(
      ...curves.flat().map((p) => p.s11_db),
      band.s11_db_max,
      BW_LEVEL_DB,
    );
    const y0 = Math.max(-60, Math.min(-15, Math.floor((dbMin - 2) / 5) * 5));

    const X = (f: number) => PAD.left + ((f - x0) / (x1 - x0)) * plotW;
    const Y = (db: number) => PAD.top + ((0 - db) / (0 - y0)) * plotH;
    const path = (c: SimResult["s11_curve"]) =>
      c.map((p, i) => `${i ? "L" : "M"}${X(p.f_ghz).toFixed(1)},${Y(p.s11_db).toFixed(1)}`).join("");

    const dbStep = y0 <= -40 ? 10 : 5;
    const yTicks: number[] = [];
    for (let v = 0; v >= y0; v -= dbStep) yTicks.push(v);

    return {
      plotW,
      plotH,
      X,
      Y,
      y0,
      path,
      xTicks: niceTicks(x0, x1, Math.max(2, Math.floor(plotW / 78))),
      yTicks,
      decimals: x1 - x0 < 1 ? 2 : 1,
      span: bandwidthSpan(res.s11_curve),
    };
  }, [w, h, res, others, band]);

  return (
    <div ref={ref} className="relative min-h-0 flex-1">
      {g && (
        <svg width={w} height={h} className="absolute inset-0" role="img"
          aria-label={`S11 against frequency. Resonance ${res.resonant_ghz.toFixed(3)} gigahertz at ${res.s11_min_db.toFixed(1)} decibels, target ${band.s11_db_max} decibels across ${band.f_low_ghz} to ${band.f_high_ghz} gigahertz.`}
        >
          <defs>
            <clipPath id={clip}>
              <rect x={PAD.left} y={PAD.top} width={g.plotW} height={g.plotH} />
            </clipPath>
          </defs>

          {/* The band the design has to work in. */}
          <rect
            x={g.X(band.f_low_ghz)}
            y={PAD.top}
            width={Math.max(g.X(band.f_high_ghz) - g.X(band.f_low_ghz), 1)}
            height={g.plotH}
            className="fill-ink-800"
          />
          {[band.f_low_ghz, band.f_high_ghz].map((f) => (
            <line
              key={f}
              x1={g.X(f)}
              x2={g.X(f)}
              y1={PAD.top}
              y2={PAD.top + g.plotH}
              className="stroke-ink-600"
