const FileIn = () => (
  <Icon
    path={
      <>
        <path d="M8 2.5v6.5" />
        <path d="M5.5 6.5 8 9l2.5-2.5" />
        <path d="M2.75 10.5v2a1 1 0 0 0 1 1h8.5a1 1 0 0 0 1-1v-2" />
      </>
    }
  />
);

const Spinner = () => (
  <Icon
    className="animate-spin"
    path={
      <>
        <circle cx="8" cy="8" r="5.25" className="opacity-25" />
