              </div>
            )}
            {!transcript.length && !planning && (
              <p className="text-[11px] leading-5 text-fg-muted">Waiting for the agent.</p>
            )}
          </div>
        )}
      </div>

      {running && (
        <form
          className="shrink-0 border-t border-ink-800 px-5 py-3"
          onSubmit={(e) => {
            e.preventDefault();
            const t = note.trim();
