          className={`absolute left-0 top-full z-20 mt-1.5 ${width} rounded-lg border border-ink-700 bg-ink-900 p-1 shadow-[0_12px_32px_rgba(0,0,0,0.5)]`}
        >
          {children(() => setOpen(false))}
        </ul>
      )}
    </div>
  );
}

